    public class AlgorithmeColorationCroissante : IAlgorithme
    {
        public string Nom => "ColorationCroissante";

        private long tempsExecution = -1;
        public long TempsExecution => tempsExecution;


        public static class ColorationCroissante
        {
            public static Dictionary<Sommet, int> Colorier(Graphe graphe)
            {
                Dictionary<Sommet, int> couleurDict = new Dictionary<Sommet, int>();

                foreach (Sommet sommet in graphe.Sommets)
                {
                    int couleur = 1;

                    while (CouleurInvalide(sommet, couleurDict, couleur))
                    {
                        couleur++;
                    }

                    couleurDict[sommet] = couleur;
                }

                return couleurDict;
            }

            private static bool CouleurInvalide(Sommet sommet, Dictionary<Sommet, int> couleurDict, int couleur)
            {
                foreach (Sommet voisin in sommet.Voisins)
                {
                    if (couleurDict.TryGetValue(voisin, out int voisinCouleur) && voisinCouleur == couleur)
                    {
                        return true;
                    }
                }

                return false;
            }
        }

